const items = [];

for (const item of $input.all()) {
  const title = (item.json.title || '').toLowerCase();
  const description = (item.json.description || item.json.content || '').toLowerCase();
  const fullText = title + ' ' + description;

  // --- Budget filter ---
  // Extract all amounts in euros from the text
  const euroMatches = fullText.match(/(\d[\d\s.,]*)(\s*k€|\s*k eur|\s*000\s*€|\s*€)/g) || [];
  const amounts = [];

  // Parse amounts like "2 000 €", "2000€", "2k€", "2.000€"
  const rawNumbers = fullText.match(/\b(\d[\d\s.,]{0,8})(?:\s*k€|\s*k eur|\s*€)/g) || [];
  for (const raw of rawNumbers) {
    let num = raw.replace(/[^\d.,k]/g, '');
    if (num.includes('k')) {
      num = parseFloat(num.replace('k', '')) * 1000;
    } else {
      num = parseFloat(num.replace(',', '.').replace(/\s/g, ''));
    }
    if (!isNaN(num)) amounts.push(num);
  }

  // Decision: pass if at least one amount is between 1000 and 10000
  // OR if no budget is mentioned at all (unknown budget)
  let budgetOk = false;
  if (amounts.length === 0) {
    // No budget mentioned → let it through
    budgetOk = true;
  } else {
    budgetOk = amounts.some(a => a >= 1000 && a <= 10000);
  }

  if (budgetOk) {
    items.push(item);
  }
}

return items;
